#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
MAIN="$ROOT/app/src/main/java/com/kaleeb/wezterm/MainActivity.java"
MANIFEST="$ROOT/app/src/main/AndroidManifest.xml"
CONTROL_SERVER="${PHONE_CONTROL_SERVER:-$HOME/.local/bin/phone-terminal-control-server}"
PHONE_TERMINAL="${PHONE_TERMINAL:-$HOME/.local/bin/phone-terminal}"
PHONE_ADB_CONNECT="${PHONE_ADB_CONNECT:-$HOME/.local/bin/phone-adb-connect}"
README="$ROOT/README.md"
INSTALL_PAGE="$ROOT/build/install.html"
INSTALL_INDEX="$ROOT/build/index.html"
RUNTIME_PROOF="$ROOT/scripts/prove-phone-runtime-regression.sh"
MENU_UI_PROOF="$ROOT/scripts/prove-phone-menu-ui.sh"
APPLE_DOC="$ROOT/docs/apple-users.md"
MACOS_PREFLIGHT="$ROOT/scripts/macos-host-preflight.sh"

require() {
    local file="$1"
    local pattern="$2"
    local message="$3"
    if ! grep -Fq -- "$pattern" "$file"; then
        echo "Phone plan regression guard failed: $message" >&2
        echo "Missing pattern: $pattern" >&2
        echo "File: $file" >&2
        exit 1
    fi
}

require_absent() {
    local file="$1"
    local pattern="$2"
    local message="$3"
    if grep -Fq -- "$pattern" "$file"; then
        echo "Phone plan regression guard failed: $message" >&2
        echo "Forbidden pattern: $pattern" >&2
        echo "File: $file" >&2
        exit 1
    fi
}

# WHY: this source-level audit is intentionally broad. The phone plan records a
# pattern of fixes regressing older fixes: scroll removing recovery, reconnect
# removing auto-reload, swipe fixes breaking typing, and toolbar cleanup hiding
# required controls. These cheap guards run before every APK build so a future
# edit cannot silently remove the protected behavior again.
require "$MANIFEST" 'android:versionCode="72"' "current APK version must be bumped for the Active Sessions action-row hotfix"
require "$MANIFEST" 'android:versionName="1.71"' "current APK version must be bumped for the Active Sessions action-row hotfix"
require "$MANIFEST" 'android:windowSoftInputMode="adjustResize"' "activity must resize for IME without activity-start keyboard forcing"
require_absent "$MANIFEST" 'stateVisible|adjustResize' "activity-start IME forcing must not return"
require "$MANIFEST" 'android.intent.action.SEND' "WEzterm must remain an Android share target for screenshots/media"
require "$MANIFEST" 'android.intent.action.SEND_MULTIPLE' "WEzterm must accept multiple shared media files"
if [ -f "$README" ]; then
    # WHY: the APK can be correct while the public handoff still serves stale
    # install/proof text. Guard the docs that the phone actually opens so future
    # work cannot pass source checks while advertising an old build again.
    require "$README" 'Built checkpoint: `versionCode=72`, `versionName=1.71`.' "README checkpoint must match the installed v1.71 APK"
    require "$README" 'v1.46 adds a bounded ACTION_UP fling burst' "README must document the fast-flick physical-proof fix"
    require "$README" 'v1.48 collapses stacked focus/IME retry bursts' "README must document the duplicate-typing focus regression fix"
    require "$README" 'v1.49 marks every WebView load/reload as a new transport generation' "README must document the stale watchdog/reload regression fix"
    require "$README" 'v1.50 makes session titles wrap to full text' "README must document the full-title session picker fix"
    require "$README" 'v1.51 separates Active Sessions from Old Sessions' "README must document the Active/Old session picker fix"
    require "$README" 'v1.52 adds no-USB phone media uploads' "README must document the phone media upload fix"
    require "$README" 'v1.53 smooths the one-finger down-scroll return path' "README must document the down-scroll bottom-edge smoothing fix"
    require "$README" 'v1.54 removes the ambiguous combined interrupt/send action' "README must document the Start/Stop split"
    require "$README" 'lightweight `/touch-scroll` server path' "README must document the low-latency touch-scroll path"
    require "$README" 'opens new phone-created sessions in `/home/cabule`' "README must document the new-session cwd fix"
    require "$README" 'v1.55 restores phone voice input' "README must document the voice-input IME hotfix"
    require "$README" 'v1.55 tried to make Active Sessions switching repaint the phone immediately' "README must document the active-switch repaint attempt"
    require "$README" 'v1.56 removed the automatic gesture-end live-bottom restore' "README must document the bottom-refresh loop fix"
    require "$README" 'v1.57 exits tmux copy-mode quietly at one-finger live bottom' "README must document the quiet touch-bottom fix"
    require "$README" 'v1.57 removes the WebView reload from Active Sessions switching' "README must document the no-reload Active switch fix"
    require "$README" 'v1.57 also moves normal `Scroll -> Go to live bottom / type`' "README must document the fast live-bottom no-refresh fix"
    require "$README" 'v1.57 makes the visible `Scroll` dialog scroll-only again' "README must document the scroll-only menu fix"
    require "$README" 'v1.57 makes passive Android lifecycle callbacks passive' "README must document the passive focus/page-finished fix"
    require "$README" 'v1.58 makes tap-to-type a single keyboard focus burst' "README must document the duplicate typing focus hotfix"
    require "$README" 'v1.59 increases the one-finger downward return-to-live cap' "README must document the downward return speed hotfix"
    require "$README" 'v1.60 raises the downward return cap to the control server' "README must document the 20-line downward return speed hotfix"
    require "$README" 'v1.61 treats a tiny tmux `lineDown` remainder as the live-bottom edge' "README must document the near-bottom restore hotfix"
    require "$README" 'v1.62 widens that quiet near-bottom restore band to 16 lines' "README must document the v1.62 near-bottom threshold"
    require "$README" 'v1.63 removes the unconditional delayed keyboard retry from tap-to-type' "README must document the duplicate typing retry hotfix"
    require "$README" 'v1.64 removes activity-start keyboard requests and guards late generic control callbacks' "README must document the duplicate typing IME hotfix"
    require "$README" 'v1.65 makes terminal-body taps single-owner' "README must document the body-tap duplicate typing hotfix"
    require "$README" 'v1.66 moves normal phone typing into a docked native composer' "README must document the native composer duplicate typing hotfix"
    require "$README" 'v1.67 removes the stale hidden composer action row' "README must document the hidden composer row cleanup"
    require "$README" 'v1.68 refits ttyd/xterm after Android WebView layout changes' "README must document the zoomed bottom/full-area hotfix"
    require "$README" 'v1.69 makes plain toolbar buttons consume their own in-bounds tap' "README must document the Active toolbar tap reliability hotfix"
    require "$README" 'v1.70 pins the current active tmux window at the top of Active Sessions' "README must document the current-first Active Sessions hotfix"
    require "$README" 'v1.71 moves the Active Sessions actions into a compact in-dialog row' "README must document the Active Sessions action-row hotfix"
    require "$README" 'full multi-word phone clipboard paste' "README must document the full-text clipboard paste proof"
    require "$README" 'direct `Bottom` toolbar button' "README must document the direct bottom button"
    require "$README" 'keeps keyboard height out of' "README must document the toolbar/IME height hotfix"
    require "$README" "the toolbar's own layout height" "README must document that keyboard height is not toolbar height"
    require "$README" 'two rows with ripple/tap feedback' "README must document the toolbar feedback/readability fix"
    require "$README" 'direct `Upload` toolbar button' "README must document the direct media upload toolbar button"
    require "$README" 'streams to disk with a 2 GB cap' "README must document video-safe media streaming"
    require "$README" 'Latest no-USB package proof used the Tailscale ADB relay' "README must document the no-USB proof path"
    require "$README" 'Apple User Support' "README must document the Apple/macOS support path"
    require "$README" 'tmux runs on macOS' "README must not imply tmux is Linux-only"
    require "$README" 'Safari/Add to Home Screen' "README must explain the iOS client path"
fi
if [ -f "$APPLE_DOC" ]; then
    require "$APPLE_DOC" 'Mac as the terminal host' "Apple doc must support Mac host users"
    require "$APPLE_DOC" 'iPhone or iPad as the client' "Apple doc must explain iOS client users"
    require "$APPLE_DOC" 'brew install tmux ttyd tailscale python' "Apple doc must include Homebrew dependency install"
    require "$APPLE_DOC" 'tmux is the persistence boundary' "Apple doc must preserve the tmux architecture reason"
    require "$APPLE_DOC" 'Do not tell iPhone users to install the Android APK' "Apple doc must prevent Android APK/iOS confusion"
