if [ "${PHONE_SKIP_GENERATED_PAGE_GUARD:-0}" != "1" ] && [ -f "$INSTALL_PAGE" ]; then
    require "$INSTALL_PAGE" 'WEzterm v1.71' "install page must advertise the current v1.71 APK"
    require "$INSTALL_PAGE" 'versionCode: <code>72</code>' "install page versionCode must match the manifest"
    require "$INSTALL_PAGE" 'SHA-256: <code>' "install page must publish the built APK checksum"
    require "$INSTALL_PAGE" 'no-refresh bottom-edge scroll guards' "install page must mention the current no-refresh down-scroll fix"
    require "$INSTALL_PAGE" 'direct Upload toolbar media' "install page must mention the direct upload toolbar fix"
    require "$INSTALL_PAGE" 'streaming video-safe phone uploads' "install page must mention the video-safe upload fix"
    require "$INSTALL_PAGE" 'separate Start/Stop controls' "install page must mention the Start/Stop split"
    require "$INSTALL_PAGE" 'voice dictation' "install page must mention the voice-input fix"
    require "$INSTALL_PAGE" 'no-reload Active switching' "install page must mention the Active Sessions no-reload fix"
    require "$INSTALL_PAGE" 'one-tap Active title switching' "install page must mention one-tap Active row switching"
    require "$INSTALL_PAGE" 'deterministic plain toolbar taps' "install page must mention the Active toolbar tap reliability fix"
    require "$INSTALL_PAGE" 'current-first Active Sessions' "install page must mention the current-first Active Sessions fix"
    require "$INSTALL_PAGE" 'compact Active Sessions action row' "install page must mention the Active Sessions action-row fix"
    require "$INSTALL_PAGE" 'scroll-only Scroll menu' "install page must mention the scroll-only Scroll menu fix"
    require "$INSTALL_PAGE" 'fast no-refresh live-bottom typing recovery' "install page must mention the fast live-bottom route"
    require "$INSTALL_PAGE" 'passive upload/page-finished focus guards' "install page must mention passive upload/page-finished focus guards"
    require "$INSTALL_PAGE" 'native composer typing' "install page must mention the duplicate typing native composer hotfix"
    require "$INSTALL_PAGE" 'no direct WebView IME typing for terminal-body taps' "install page must mention direct WebView IME typing is disabled"
    require "$INSTALL_PAGE" 'no activity-start IME request' "install page must mention the no-implicit-IME hotfix"
    require "$INSTALL_PAGE" 'late-control IME guard' "install page must mention the late-control focus guard"
    require "$INSTALL_PAGE" '20-line bounded downward return' "install page must mention the downward return speed hotfix"
    require "$INSTALL_PAGE" '16-line near-bottom quiet restore' "install page must mention the near-bottom restore hotfix"
    require "$INSTALL_PAGE" 'quiet touch-bottom copy-mode exit' "install page must mention quiet one-finger bottom restore"
    require "$INSTALL_PAGE" 'two-row toolbar tap feedback' "install page must mention visible tap feedback"
    require "$INSTALL_PAGE" 'safe control retry' "install page must mention bounded control retry"
    require "$INSTALL_PAGE" 'lightweight tmux touch-scroll gestures' "install page must mention the low-latency touch-scroll fix"
    require "$INSTALL_PAGE" 'native composer typing' "install page must mention the native composer typing fix"
    require "$INSTALL_PAGE" 'full multi-word clipboard paste' "install page must mention full-text Copy/Paste proof"
    require "$INSTALL_PAGE" 'direct Bottom button' "install page must mention the direct bottom button"
    require "$INSTALL_PAGE" 'zoomed true-bottom viewer reach' "install page must mention the zoomed bottom/full-area fix"
fi
if [ "${PHONE_SKIP_GENERATED_PAGE_GUARD:-0}" != "1" ] && [ -f "$INSTALL_INDEX" ]; then
