fi
if [ -f "$RUNTIME_PROOF" ]; then
    require "$RUNTIME_PROOF" 'sessions activity groups' "runtime proof must check session/date picker data"
    require "$RUNTIME_PROOF" 'old parent sessions by date' "runtime proof must check old parent Codex sessions"
    require "$RUNTIME_PROOF" 'old sessions exclude subagents' "runtime proof must prove subagent sessions stay out"
    require "$RUNTIME_PROOF" 'resume-session dry-run' "runtime proof must check Old Sessions resume command without spawning a session"
    require "$RUNTIME_PROOF" 'needs-attention endpoint' "runtime proof must check Needs Attention data"
    require "$RUNTIME_PROOF" 'touch-scroll endpoint' "runtime proof must check one-finger scroll routing"
    require "$RUNTIME_PROOF" 'extra down at live bottom stays stopped' "runtime proof must check bottom-edge down-scroll does not bounce"
    require "$RUNTIME_PROOF" 'paste endpoint full text' "runtime proof must check Copy/Paste paste route with spaces"
    require "$RUNTIME_PROOF" 'copy-visible endpoint' "runtime proof must check Copy/Paste copy route"
    require "$RUNTIME_PROOF" 'media upload endpoint' "runtime proof must check phone media upload route"
    require "$RUNTIME_PROOF" 'chunked media upload endpoint' "runtime proof must check video-style chunked media upload route"
    require "$RUNTIME_PROOF" 'new session cwd is /home/cabule' "runtime proof must check phone New opens in /home/cabule"
    require "$RUNTIME_PROOF" 'select-live endpoint' "runtime proof must check fast Active Sessions switching"
    require "$RUNTIME_PROOF" 'live-bottom fast endpoint' "runtime proof must check the fast no-refresh live-bottom route"
    require "$RUNTIME_PROOF" 'touch-scroll endpoint' "runtime proof must check low-latency one-finger scroll routing"
    require "$RUNTIME_PROOF" 'send-enter endpoint' "runtime proof must check Start/Enter route"
    require "$RUNTIME_PROOF" 'submit-text endpoint' "runtime proof must check safe native prompt route"
    require "$RUNTIME_PROOF" 'stop endpoint double escape' "runtime proof must check Stop route"
    require "$RUNTIME_PROOF" 'stable windowId close' "runtime proof must check exact disposable-tab close"
    require "$RUNTIME_PROOF" 'restore original phone tab' "runtime proof must restore the user's tab"
fi
if [ -f "$MENU_UI_PROOF" ]; then
    require "$MENU_UI_PROOF" 'uiautomator dump' "menu UI proof must use the real installed phone UI"
    require "$MENU_UI_PROOF" 'phone menu UI proof failed at line' "menu UI proof must report exact failing commands instead of silent exits"
    require "$MENU_UI_PROOF" 'for label in Active Old New Refresh Bottom Scroll "Copy/Paste" Upload Close Start Stop' "menu UI proof must check every bottom toolbar label"
    require "$MENU_UI_PROOF" 'tap_text "Old"' "menu UI proof must open Old Sessions"
    require "$MENU_UI_PROOF" 'assert_text "Old Sessions"' "menu UI proof must verify the Old Sessions dialog"
    require "$MENU_UI_PROOF" 'assert_text "Resume"' "menu UI proof must verify old-session resume actions"
    require "$MENU_UI_PROOF" 'New button created' "menu UI proof must prove New creates a disposable session"
    require "$MENU_UI_PROOF" 'Old Resume button opened' "menu UI proof must prove Old Sessions Resume opens a session"
    require "$MENU_UI_PROOF" 'Refresh button restored live mode' "menu UI proof must prove Refresh fixes the live view"
    require "$MENU_UI_PROOF" 'Page up' "menu UI proof must exercise Scroll Page up"
    require "$MENU_UI_PROOF" 'Page down' "menu UI proof must exercise Scroll Page down"
    require "$MENU_UI_PROOF" 'Go to live bottom / type' "menu UI proof must exercise live-bottom recovery"
    require "$MENU_UI_PROOF" 'open_scroll_menu()' "menu UI proof must robustly open the scroll-only menu from toolbar state"
    require "$MENU_UI_PROOF" 'Direct Bottom button returned to live typing' "menu UI proof must exercise the one-tap Bottom toolbar button"
    require "$MENU_UI_PROOF" 'Terminal and toolbar bounds do not overlap' "menu UI proof must prove toolbar buttons do not cover the terminal bottom"
    require "$MENU_UI_PROOF" 'Scroll menu is scroll-only' "menu UI proof must prove Scroll is not the old giant controls menu"
    require "$MENU_UI_PROOF" 'Active row title switched with one tap' "menu UI proof must tap an Active title row exactly once"
    require "$MENU_UI_PROOF" 'assert_text "Rename"' "menu UI proof must verify the Active Sessions compact action row"
    require "$MENU_UI_PROOF" 'dragging the finger down moves into older tmux history' "menu UI proof must document the protected physical swipe direction"
    require "$MENU_UI_PROOF" 'terminal_swipe()' "physical scroll proof must compute real terminal bounds instead of hardcoded portrait coordinates"
    require "$MENU_UI_PROOF" 'terminal_tap_for_typing()' "tap-to-type proof must compute real terminal bounds instead of hardcoded portrait coordinates"
    require "$MENU_UI_PROOF" 'resource_id == "terminal-container"' "physical scroll proof must prefer the actual terminal container bounds"
    require "$MENU_UI_PROOF" 'terminal_swipe history-slow 900' "slow physical scroll proof must drag finger down from live bottom into history"
